<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
use WexaShelf\WorkerHeartbeat;
$storage=sys_get_temp_dir().'/wexa-heartbeat-'.bin2hex(random_bytes(8));mkdir($storage,0700);$prior=getenv('WEXA_STORAGE_PATH');putenv('WEXA_STORAGE_PATH='.$storage);
function beatCheck(bool $v,string $message):void{if(!$v)throw new RuntimeException($message);}
try{beatCheck(WorkerHeartbeat::read('ai')===null,'Missing evidence unknown');beatCheck(WorkerHeartbeat::record('ai','completed',999,microtime(true)),'Atomic write');$v=WorkerHeartbeat::read('ai');beatCheck($v['processed']===20&&$v['status']==='completed','Bounded fields');beatCheck((fileperms($storage.'/worker-runs/ai.json')&0777)===0600,'Private permissions');$v['secret']='must-not-leak';file_put_contents($storage.'/worker-runs/ai.json',json_encode($v));beatCheck(!isset(WorkerHeartbeat::read('ai')['secret']),'Read whitelist');beatCheck(!WorkerHeartbeat::record('../unsafe','failed',0,microtime(true)),'Queue path whitelist');file_put_contents($storage.'/worker-runs/ai.json','broken');beatCheck(WorkerHeartbeat::read('ai')===null,'Corrupt evidence unknown');unlink($storage.'/worker-runs/ai.json');rmdir($storage.'/worker-runs');file_put_contents($storage.'/worker-runs','blocked');beatCheck(!WorkerHeartbeat::record('ai','failed',0,microtime(true)),'Recording failure does not throw');echo "PASS heartbeat private atomic evidence, bounded whitelist, invalid/corrupt paths and nonfatal write failure.\n";}finally{foreach(glob($storage.'/worker-runs/*')?:[]as$f)unlink($f);if(is_dir($storage.'/worker-runs'))rmdir($storage.'/worker-runs');elseif(is_file($storage.'/worker-runs'))unlink($storage.'/worker-runs');rmdir($storage);putenv($prior===false?'WEXA_STORAGE_PATH':'WEXA_STORAGE_PATH='.$prior);}
